        contextLabel=Aero.text(c,"Type “open Audible” and press Send to launch an app, or ask for help with writing.",12,0xff666666);contextLabel.setPadding(Aero.dp(c,8),Aero.dp(c,6),Aero.dp(c,8),Aero.dp(c,8));contextLabel.setMaxLines(2);contextLabel.setEllipsize(android.text.TextUtils.TruncateAt.END);contextLabel.setContentDescription("Nota context source");contextLabel.setOnClickListener(v->{if(context!=null)Aero.dialog(c).setTitle("Context from "+context.title).setMessage("The text in the composer is the only passage used for this request. Edit it before sending. Clearing context keeps your draft.").setPositiveButton("Keep",null).setNeutralButton("Clear context",(d,w)->{context=null;contextLabel.setText("Context cleared · review your message before Send");clearContext();}).show();});addView(contextLabel);
        ScrollView scroll=new ScrollView(c);replyScroll=scroll;scroll.setFillViewport(true);LinearLayout reply=Aero.column(c);answer=Aero.text(c,store.prefs.getString("ten_nota_reply","Ask me to open Nth Browser, open a Settings page, or help with your writing. Ask “What can you do?” for examples."),16,Aero.INK);answer.setTextIsSelectable(true);Aero.pad(answer,12);actionChoices=Aero.column(c);actionChoices.setContentDescription("Nota desktop actions");reply.addView(actionChoices,new LayoutParams(-1,-2));reply.addView(answer);scroll.addView(reply);addView(scroll,new LayoutParams(-1,0,1));
        LinearLayout replyTools=new LinearLayout(c);replyTools.addView(button("Copy reply",this::copy),new LayoutParams(0,Aero.dp(c,40),1));replyTools.addView(button("Save to Notepad",this::save),new LayoutParams(0,Aero.dp(c,40),1));apply=button("Apply to source",this::applyReply);apply.setContentDescription("Apply Nota reply to source");apply.setVisibility(GONE);replyTools.addView(apply,new LayoutParams(0,Aero.dp(c,40),1));addView(replyTools);
        HorizontalScrollView suggestions=new HorizontalScrollView(c);suggestions.setHorizontalScrollBarEnabled(false);LinearLayout chips=new LinearLayout(c);String[] labels={"Draft content","Brainstorm","Proofread","Polish","Summarize"};for(int i=0;i<labels.length;i++){final int index=i;TextView chip=button(labels[i],()->chooseTask(index));LayoutParams p=new LayoutParams(-2,Aero.dp(c,42));p.setMargins(Aero.dp(c,3),0,Aero.dp(c,3),0);chips.addView(chip,p);}for(String example:TenNotaActions.EXAMPLES){TextView chip=button(example,()->example(example));chip.setContentDescription("Try command: "+example);chips.addView(chip,0,new LayoutParams(-2,Aero.dp(c,42)));}suggestions.addView(chips);suggestions.setContentDescription("Nota writing and desktop suggestions");addView(suggestions);
